using System.IO;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
namespace DanceStudio;
public sealed record SourceFingerprint(long Size,string Sha256);
public sealed record MissingSource(string Kind,string Path,SourceFingerprint? Fingerprint);
public static class ProjectRelink {
 public static Dictionary<string,string> Paths(SongProject p)=>new(){{"dance",p.Dance.Path},{"camera",p.Camera.Path},{"audio",p.Audio.Path},{"skeleton",p.Skeleton}};
 public static List<MissingSource> Missing(SongProject p)=>Paths(p).Where(kv=>kv.Value.Length>0&&!Rig.IsBuiltin(kv.Value)&&!File.Exists(kv.Value)).Select(kv=>new MissingSource(kv.Key,kv.Value,p.SourceFingerprints.GetValueOrDefault(kv.Key))).ToList();
 public static SourceFingerprint Fingerprint(string path){using var f=File.OpenRead(path);return new(f.Length,Convert.ToHexStringLower(SHA256.HashData(f)));}
 public static SongProject Copy(SongProject p)=>JsonSerializer.Deserialize<SongProject>(JsonSerializer.Serialize(p,SongProject.Json),SongProject.Json)!;
 public static SongProject Apply(SongProject p,IReadOnlyDictionary<string,string> paths){var next=Copy(p);foreach(var entry in paths){string file=System.IO.Path.GetFullPath(entry.Value);if(!File.Exists(file))throw new FileNotFoundException(file);switch(entry.Key){case "dance":next.Dance.Path=file;break;case "camera":next.Camera.Path=file;break;case "audio":next.Audio.Path=file;break;case "skeleton":next.Skeleton=file;break;default:throw new InvalidDataException("Unknown source kind");}}ProjectRules.Validate(next);return next;}
 public static SongProject? Dialog(Window owner,SongProject original){var missing=Missing(original);if(missing.Count==0)return Copy(original);var replacements=new Dictionary<string,string>();var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(new TextBlock{Text=UiText.T("releaseRelinkHelp"),TextWrapping=TextWrapping.Wrap,MaxWidth=720,Margin=new Thickness(0,0,0,12)});var dialog=new Window{Owner=owner,Title=UiText.T("releaseRelink"),Width=800,SizeToContent=SizeToContent.Height,MaxHeight=650,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}};foreach(var item in missing){var row=new StackPanel{Margin=new Thickness(0,5,0,12)};panel.Children.Add(row);row.Children.Add(new TextBlock{Text=UiText.T("releaseSource_"+item.Kind)+" · "+System.IO.Path.GetFileName(item.Path),FontWeight=FontWeights.Bold});row.Children.Add(new TextBlock{Text=item.Path,TextWrapping=TextWrapping.Wrap});var state=new TextBlock{Text=UiText.T("releaseMissing"),TextWrapping=TextWrapping.Wrap};row.Children.Add(state);var choose=new Button{Content=UiText.T("releaseChooseSource"),HorizontalAlignment=HorizontalAlignment.Left};row.Children.Add(choose);choose.Click+=async(_,_)=>{var file=new OpenFileDialog{Filter=item.Kind=="audio"?"Audio|*.wav;*.xwm;*.wxm":"HKX|*.hkx",FileName=System.IO.Path.GetFileName(item.Path)};if(file.ShowDialog(dialog)!=true)return;choose.IsEnabled=false;try{var proof=await Task.Run(()=>Fingerprint(file.FileName));replacements[item.Kind]=file.FileName;state.Text=file.FileName+"\n"+UiText.T(item.Fingerprint==null?"releaseIdentityUnknown":item.Fingerprint==proof?"releaseIdentityMatch":"releaseIdentityChanged");}catch(Exception e){state.Text=e.Message;}finally{choose.IsEnabled=true;}};}
  var actions=new WrapPanel();panel.Children.Add(actions);var accept=new Button{Content=UiText.T("releaseReconnect")};var cancel=new Button{Content=UiText.T("releaseCancel")};actions.Children.Add(accept);actions.Children.Add(cancel);SongProject? result=null;accept.Click+=(_,_)=>{if(replacements.Count!=missing.Count){MessageBox.Show(dialog,UiText.T("releaseRelinkAll"));return;}result=Apply(original,replacements);dialog.DialogResult=true;};cancel.Click+=(_,_)=>dialog.DialogResult=false;return dialog.ShowDialog()==true?result:null;
 }
}
